import { test } from 'node:test';
import assert from 'node:assert/strict';
import { total, itemCount } from '../src/cart.js';

test('total without discount', () => {
  assert.equal(total([{ price: 100, qty: 2 }, { price: 50, qty: 1 }]), 250);
});

// A cart of `n` lines, each one item at `price`.
const lines = (n, price) => Array.from({ length: n }, () => ({ price, qty: 1 }));

// Issue #12: the customer discount is applied once.
test('total applies the customer discount once (under 10 lines)', () => {
  assert.equal(total([{ price: 1000, qty: 1 }], 0.1), 900); // 1000 * 0.9
});

test('total applies the customer discount, then the 5% bulk discount once (10 lines)', () => {
  assert.equal(total(lines(10, 1000), 0.1), 8550); // 10000 * 0.9 * 0.95
});

test('total applies no bulk discount to a 9-line cart with a customer discount', () => {
  assert.equal(total(lines(9, 1000), 0.1), 8100); // 9000 * 0.9
});

// Issue #12: totals with a discount rate of 0 stay as they were.
test('total with discount 0 applies only the bulk discount (10 lines)', () => {
  assert.equal(total(lines(10, 1000), 0), 9500); // 10000 * 0.95
});

test('total with discount 0 and under 10 lines is the subtotal', () => {
  assert.equal(total(lines(9, 1000), 0), 9000);
});

test('item count', () => {
  assert.equal(itemCount([{ price: 1, qty: 3 }, { price: 1, qty: 2 }]), 5);
});
